-- =====================================================================
-- HYATHLON INSTALL · PART 3b · rehab update after review
-- Run AFTER Part 3. Paste into Supabase → SQL Editor → New query → Run.
-- Replaces the rehab programs with the revised versions. One transaction.
-- =====================================================================
begin;

alter table public.rehab_programs
  add column if not exists discharge_criteria text[] not null default '{}',
  add column if not exists seek_assessment text,
  add column if not exists clinician_required boolean not null default false,
  add column if not exists clinician_notes text[] not null default '{}',
  add column if not exists physio_review_points text[] not null default '{}';
alter table public.rehab_programs alter column disclaimer set default 'This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.';

-- Guidance shown on every rehab program (e.g. the "Stop and seek advice" box)
create table if not exists public.rehab_global_guidance (
  key text primary key,
  title text not null,
  items text[] not null
);
alter table public.rehab_global_guidance enable row level security;
drop policy if exists "rehab guidance read" on public.rehab_global_guidance;
drop policy if exists "rehab guidance coach write" on public.rehab_global_guidance;
create policy "rehab guidance read" on public.rehab_global_guidance for select to authenticated using (true);
create policy "rehab guidance coach write" on public.rehab_global_guidance for all to authenticated using (public.is_coach()) with check (public.is_coach());
on conflict (key) do update set title = excluded.title, items = excluded.items;

-- Replace programs (phases and exercises are removed with them)
delete from public.rehab_programs;
delete from public.return_to_run_plans;








-- Check: should show 10 | 32 | 7
select (select count(*) from public.rehab_programs) as programs,
       (select count(*) from public.rehab_phases) as phases,
       (select array_length(items,1) from public.rehab_global_guidance where key='stop_and_seek_advice') as stop_items;

commit;
