insert into public.rehab_global_guidance (key, title, items) values
  ('stop_and_seek_advice', 'Stop and seek advice if you notice', array['Pain above 5/10, or sharp pain that makes you limp or change how you move','Pain that is worse the next morning after two sessions in a row','New swelling, bruising, locking or the joint giving way','Numbness, tingling or weakness','Pain at night or at rest, fever, or feeling unwell','Calf swelling, warmth and tenderness, chest pain or breathlessness: seek urgent care','No clear improvement after 4–6 weeks of following the program']::text[]),
  ('disclaimer', 'About these programs', array['This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.']::text[])
insert into public.rehab_programs (id,name,also_known_as,body_area,overview,red_flags,pain_rule,typical_duration,disclaimer,discharge_criteria,seek_assessment,clinician_required,clinician_notes,physio_review_points) values
('mtss','Shin splints','Medial tibial stress syndrome (MTSS)','Lower leg','Diffuse pain along the inner border of the shin, usually from a rise in running load. The aim is to settle the bone and muscle, rebuild calf and shin capacity, then rebuild running.',array['Pain in one small spot on the bone (possible bone stress injury: see a professional before continuing)','Pain when resting or at night','Pain that gets worse with each hop on one leg','Tight, burning or numb lower leg during exercise that eases with rest (possible compartment syndrome)']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step.','6–12 weeks','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['25+ single-leg calf raises each side, with the injured side within 10% of the other (LSI ≥90%)','Single-leg hop for distance LSI ≥90%','2 × 20 single-leg pogo hops each side, pain-free','2 weeks at pre-injury running volume with no symptoms']::text[],'Get assessed if pain becomes focal on the bone, or there is no improvement after 3–4 weeks.',false,'{}'::text[],array['Is a symptom-guided progression preferred over any fixed weekly increase for this group?','Should a hop test be required before starting Phase 3?']::text[]),
('pfps','Runner''s knee','Patellofemoral pain (PFP)','Knee','Pain around or behind the kneecap, worse with stairs, squats, downhill running or sitting for long periods. The aim is to calm the knee, then build quad and hip strength.',array['Knee locking, catching or giving way','Swelling, especially after a twist or fall','Pain on the joint line at the side of the knee','Pain at rest or at night']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step.','6–12 weeks','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['10 single-leg squats to a box each side with good knee control (knee stays over the foot)','Single-leg hop for distance and triple hop LSI ≥90%','Quad and hip abduction strength within 10% side to side (if a dynamometer is available)','Stairs, squats, downhill running and full training pain-free']::text[],'Get assessed if there is no clear improvement after 6 weeks.',false,'{}'::text[],array['Knee angle limits for Phase 2 loading (e.g. leg press 0–60°)?','Which functional tests to use at discharge?']::text[]),
('bsi','Bone stress injury return','Lower-leg bone stress injury (low-risk sites)','Lower leg / foot','For a diagnosed low-risk bone stress injury (for example the back or inner tibia, fibula, or 2nd–4th metatarsal) once a doctor or physio has cleared you to start loading. It is not for high-risk sites.',array['Not yet diagnosed or cleared by a medical professional: do not start','High-risk sites need medical management and are not covered here: front of the tibia, navicular, base of the 5th metatarsal, inner ankle bone, femoral neck','Any bone pain when walking, hopping or at rest','Repeat bone stress injuries, missed or irregular periods, or low energy intake: ask about RED-S screening']::text[],'Bone stress injuries must be pain-free: 0/10 bone pain during activity and in the 24 hours after. Any bone pain means stop and drop back to the previous step.','12–20 weeks from diagnosis','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['Full training for 4 weeks with no bone pain','25+ single-leg calf raises each side, LSI ≥90%','Single-leg hop for distance LSI ≥90%, pain-free','Medical sign-off for return to speed work and racing']::text[],'Every step of this program needs a doctor or physio overseeing it. Get reassessed immediately if bone pain returns.',true,array['Site matters. Low-risk sites (back/inner tibia, fibula, 2nd–4th metatarsal) can usually follow a staged return. High-risk sites (front of the tibia, navicular, base of the 5th metatarsal, inner ankle, femoral neck) need medical management and are excluded.','Timelines depend on site, imaging grade and the individual; the clinician sets the start of each phase.','RED-S screening: check energy intake, menstrual function (irregular or absent periods), low libido in males, previous bone stress injuries, recent weight loss and fatigue. Refer to a sports doctor and sports dietitian if any are present; bone density assessment may be indicated.','Return-to-run criteria (hop test, pain-free walking, bone tenderness) to be confirmed by the treating clinician.']::text[],array['Confirm return-to-run criteria and the bone-stress run plan.','Confirm site-specific exclusions and timelines.','Confirm the RED-S screening questions and referral pathway.']::text[]),
('achilles_mid','Achilles tendinopathy (mid-portion)','Mid-portion Achilles tendinopathy','Lower leg','Pain and thickening 2–6 cm above the heel, with morning stiffness, often after a rise in speed, hills or volume. Tendons respond to progressive loading, so rest alone rarely fixes it.',array['A sudden pop or feeling of being kicked in the back of the leg (possible rupture: see a doctor urgently)','Unable to do a single-leg calf raise','Marked swelling or a lump that is hot and red','Recent fluoroquinolone antibiotics (for example ciprofloxacin)','Pain in both Achilles plus other joints']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step. For the Achilles, also track morning stiffness: it should not get worse from week to week.','12 weeks or more','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['25+ single-leg calf raises each side, LSI ≥90%','Weighted single-leg calf raise 3 × 8 each side','2 × 20 single-leg pogo hops each side at pain ≤2/10','Morning stiffness resolved; VISA-A score improving if your physio uses it']::text[],'Get assessed if there is no clear improvement after 6–8 weeks of loading.',false,'{}'::text[],array['Pain threshold during loading: ≤3/10 as written, or the Silbernagel ≤5/10 model?','Keep eccentric heel drops alongside heavy slow resistance?']::text[]),
('achilles_ins','Achilles tendinopathy (insertional)','Insertional Achilles tendinopathy','Lower leg','Pain where the Achilles attaches to the back of the heel, often worse with uphill running, stretching the calf and flat or barefoot shoes. Loading is similar to the mid-portion program, but the heel stays on flat ground so the tendon isn''t compressed against the heel bone.',array['A sudden pop or feeling of being kicked in the back of the leg (possible rupture: see a doctor urgently)','Unable to do a single-leg calf raise','Marked swelling or a lump that is hot and red','Recent fluoroquinolone antibiotics (for example ciprofloxacin)','Pain in both Achilles plus other joints']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step. For the Achilles, also track morning stiffness: it should not get worse from week to week.','12 weeks or more','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['25+ single-leg calf raises on flat ground each side, LSI ≥90%','Weighted calf raise 3 × 8 each side on flat ground','Pogo hops and uphill running pain-free','Morning stiffness resolved']::text[],'Get assessed if there is no clear improvement after 8 weeks, or if there is a hard lump or redness at the back of the heel.',false,'{}'::text[],array['Use of a heel raise in shoes early on, and when to wean off it?','When to reintroduce range below flat and uphill running?']::text[]),
('plantar','Plantar fasciitis','Plantar heel pain','Foot','Pain under the heel, typically worst with the first steps in the morning or after sitting. The aim is to settle it and then strengthen the foot and calf with slow, heavy loading.',array['Numbness, tingling or burning in the foot (possible nerve involvement)','Pain when the heel is squeezed from both sides (possible heel bone stress injury)','Swelling, redness or heat','Night pain','Pain in both heels together with other joints']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step.','8–16 weeks','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['12 slow single-leg heel raises with toes elevated each side, LSI ≥90%','2 × 20 pogo hops pain-free','No first-step pain in the morning','Full training for 2 weeks without symptoms']::text[],'Get assessed if there is no clear improvement after 6–8 weeks, or if symptoms include numbness or burning.',false,'{}'::text[],array['Is the Rathleff protocol dosing appropriate as written?']::text[]),
('itbs','IT band syndrome','Iliotibial band syndrome (ITBS)','Hip / knee','Sharp pain on the outside of the knee that comes on at a predictable distance, often worse downhill. The aim is to manage running load and build hip strength and control.',array['Swelling in the knee','Locking or giving way','Pain after a twist or fall','Pain at rest']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step.','6–10 weeks','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['Side plank 45 s each side with good alignment','10 single-leg squats each side with good control','Single-leg hop for distance LSI ≥90%','Long runs and downhills pain-free']::text[],'Get assessed if there is no clear improvement after 4–6 weeks.',false,'{}'::text[],array['Keep foam rolling as a comfort-only option or remove it?']::text[]),
('calf','Calf strain','Gastrocnemius or soleus strain','Lower leg','A sudden sharp pain or pull in the calf, often during speed, hills or sled work. Soleus strains (deep, lower calf) usually take longer than gastrocnemius strains.',array['A pop and being unable to rise onto the toes (rule out Achilles rupture)','Calf swelling, warmth and tenderness without an injury (possible blood clot: seek urgent care)','Large bruising or a visible dent in the muscle','Unable to put weight through the leg']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step.','3–8 weeks','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['Straight-knee and bent-knee calf raise endurance LSI ≥90%','Single-leg hop for distance LSI ≥90%','Strides and repeated fast running pain-free','Sled push at race weight pain-free']::text[],'Get assessed if you can''t walk normally after a week, or if the strain recurs.',false,'{}'::text[],array['Separate timelines for gastrocnemius vs soleus strains?']::text[]),
('pht','Hamstring tendinopathy','Proximal hamstring tendinopathy','Hip / hamstring','Deep pain at the sit bone, worse with sitting, hills, speed and deep hip bending. The aim is to load the tendon progressively while avoiding positions that compress it.',array['A sudden pop with bruising at the back of the thigh (possible avulsion: see a doctor urgently)','Pain spreading down the leg with numbness or tingling (may be coming from the back)','Night pain or fever']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step. Avoid hamstring stretching and long periods of sitting on hard surfaces while symptoms are high.','12 weeks or more','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['Single-leg bridge 25+ reps each side, LSI ≥90%','Nordic hamstring curl 3 × 5 pain-free','Sitting 60 min pain-free','Full speed and hill running pain-free']::text[],'Get assessed if there is no clear improvement after 6–8 weeks, or if pain spreads down the leg.',false,'{}'::text[],array['When should hills be reintroduced? (Currently late in Phase 3, after flat strides and speed.)']::text[]),
('lbp','Hip, SIJ and lower back pain','Non-specific lower back, sacroiliac joint and hip pain','Hip / back','Pain in the lower back, the SIJ (dimples at the back of the pelvis) or around the hip without a specific structural cause. Most cases settle with staying active and gradually rebuilding trunk and hip strength.',array['Numbness around the groin or saddle area, or changes to bladder or bowel control (seek urgent care)','Weakness in the legs that is getting worse','Pain spreading below the knee with pins and needles or numbness','Severe night pain, fever, unexplained weight loss or a history of cancer','Pain after a significant fall or accident']::text[],'Pain up to 3/10 during exercise is acceptable if it settles within 24 hours and morning symptoms are no worse the next day. If pain goes above 3/10, or is worse the next morning, drop back to the previous step. Staying active helps. Avoid bed rest.','4–12 weeks','This program is educational guidance for common running injuries. It is not a diagnosis and does not replace an individual assessment by a physiotherapist or doctor. If you are unsure what your injury is, if it is severe, or if it is not improving, get assessed before continuing.',array['Side plank 60 s each side','Hip hinge and single-leg work at full training loads pain-free','Full training including heavy lifting, sleds and carries pain-free']::text[],'If symptoms persist beyond 6 weeks despite completing the program, or keep coming back, get assessed by a physio or doctor.',false,'{}'::text[],array['Which findings should trigger referral for assessment of SIJ versus lumbar sources?']::text[]);
insert into public.rehab_phases (program_id,phase_no,name,typical_duration,goal,entry_criteria,exit_criteria,frequency,running_guidance) values
('mtss',1,'Settle and load','1–2 weeks','Reduce irritation while keeping the calf and shin working.','Diffuse pain along the inner shin; walking comfortable.','Pain-free walking and daily activity; 20 single-leg calf raises each side at pain ≤2/10; 10 single-leg hops each side at pain ≤2/10.','Daily isometrics; strength every second day','Reduce running by about 50%, or replace with bike or pool running if pain is above 3/10.'),
('mtss',2,'Build capacity','2–4 weeks','Rebuild calf, soleus and shin strength and start low-level impact.','Phase 1 exit criteria met.','25 single-leg calf raises each side; pogo hops 3 × 20 pain-free; 30 min continuous easy run at pain ≤2/10 and no worse the next morning.','Strength 3 × per week','Start the Standard return-to-run plan.'),
('mtss',3,'Return to run and impact','3–6 weeks','Restore running volume and reactive strength.','Phase 2 exit criteria met.','Back to pre-injury running volume with no symptoms for 2 weeks.','Strength 2–3 × per week; plyometrics 2 × per week','Progress one variable at a time (days, then duration, then intensity) after a symptom-free week; vary surfaces; a 5% cadence increase can help.'),
('pfps',1,'Calm and activate','1–2 weeks','Settle the knee and switch on the quads and hips.','Front-of-knee pain; able to walk normally.','Stairs at pain ≤2/10; wall sit 45 s at a comfortable depth at pain ≤2/10.','Isometrics daily; hip work every second day','Keep running flat and shorter, below the distance that brings on pain; avoid downhill; raise cadence by 5–10%.'),
('pfps',2,'Build strength','3–6 weeks','Load the quads and hips through a comfortable range.','Phase 1 exit criteria met.','10 single-leg squats to a box with good knee control; 30 min run at pain ≤2/10.','3 × per week','Start the Standard return-to-run plan if you stopped, or build steadily if still running.'),
('pfps',3,'Return to full load','3–6 weeks','Heavier single-leg strength, landing control, then hills and downhills.','Phase 2 exit criteria met.','Stairs, squats, downhill running and full training pain-free.','2–3 × per week','Reintroduce hills, downhills and speed one at a time.'),
('bsi',1,'Protect and cross-train','As prescribed (often 2–6 weeks)','Let the bone heal while keeping fitness and strength.','Diagnosed low-risk bone stress injury; medical plan in place.','Pain-free walking for 30–45 min on several days in a row; no bone tenderness when pressed; medical clearance to start loading.','Cross-training 4–6 × per week; strength 2–3 × per week','No running. Pool running, bike or swimming only if pain-free.'),
('bsi',2,'Load the bone','2–4 weeks','Build calf and leg strength and walking tolerance before any impact.','Phase 1 exit criteria met.','45 min brisk walk pain-free; 20 single-leg calf raises each side pain-free; 10 single-leg hops each side at 0/10 pain.','Strength 3 × per week','No running yet. Walk daily.'),
('bsi',3,'Return to run','6–10 weeks','Rebuild running on alternate days with no bone pain.','Phase 2 exit criteria met and medical clearance to run.','30 min continuous easy running on alternate days for 2 weeks with 0/10 bone pain.','Running every second day; strength 2–3 × per week','Follow the Bone stress return-to-run plan on flat, soft surfaces. No speed work or hills.'),
('bsi',4,'Return to full training','4–8 weeks','Rebuild volume, then add speed, hills and race-specific work.','Phase 3 exit criteria met.','Back to full training with no bone pain.','Normal training','Add days before distance, and distance before speed; one change per week.'),
('achilles_mid',1,'Isometrics and load management','1–2 weeks','Reduce pain and keep the tendon loaded.','Achilles pain and morning stiffness.','Morning stiffness settling; 20 double-leg calf raises at pain ≤3/10.','Isometrics daily, can be done before runs','Keep running if pain stays ≤3/10 and morning stiffness isn''t worsening. Remove hills and speed.'),
('achilles_mid',2,'Heavy slow resistance','6–12 weeks','Rebuild tendon capacity with heavy, slow calf work.','Phase 1 exit criteria met.','25 single-leg calf raises each side, within 10% of the other leg; weighted single-leg calf raise 3 × 8.','3 × per week (48 h between sessions)','Build back to normal easy volume. Keep hills and speed out.'),
('achilles_mid',3,'Energy storage and return','4–8 weeks','Restore springiness for fast running, hills and jumping.','Phase 2 exit criteria met.','Full training including speed and hills with stable morning symptoms.','Plyometrics 2 × per week; heavy calf work 2 × per week','Add hills, then strides, then speed sessions, one per week.'),
('achilles_ins',1,'Settle and isometrics','1–2 weeks','Reduce compression on the insertion and keep the tendon loaded.','Pain at the back of the heel where the tendon attaches.','Morning stiffness settling; 20 double-leg calf raises on flat ground at pain ≤3/10.','Isometrics daily','Keep running if pain stays ≤3/10 and isn''t worse the next morning. Avoid hills, barefoot and very flat shoes; a small heel raise can help short term. Avoid calf stretching.'),
('achilles_ins',2,'Heavy slow resistance on flat ground','6–12 weeks','Rebuild tendon capacity without dropping the heel below flat.','Phase 1 exit criteria met.','25 single-leg calf raises each side on flat ground; weighted 3 × 8.','3 × per week (48 h between sessions)','Build back to normal flat volume. No hills yet.'),
('achilles_ins',3,'Range, energy storage and return','4–8 weeks','Gradually reintroduce range, spring and hills.','Phase 2 exit criteria met.','Full training including hills and speed with stable morning symptoms.','Plyometrics 2 × per week; heavy calf work 2 × per week','Add strides, then speed, then hills last. Uphill running loads the insertion most.'),
('plantar',1,'Settle','1–2 weeks','Reduce morning pain and daily irritation.','Heel pain, worse with first steps.','First-step pain ≤3/10; walking 30 min comfortable.','Stretches daily (especially before getting out of bed); strength every second day','Reduce volume; stick to supportive shoes and flatter, softer routes.'),
('plantar',2,'Strength','6–12 weeks','Strengthen the plantar fascia, foot and calf.','Phase 1 exit criteria met.','12 slow single-leg heel raises with the toes elevated, carrying load, at pain ≤2/10; first steps pain-free.','Every second day','Build back to normal easy volume.'),
('plantar',3,'Return to full load','4–6 weeks','Add impact and speed.','Phase 2 exit criteria met.','Full training with no morning pain.','2–3 × per week','Add strides, hills and speed one at a time.'),
('itbs',1,'Settle and activate','1–2 weeks','Stay below pain onset while switching on the hip muscles.','Outside-of-knee pain that comes on during runs.','30 min flat run without pain onset.','Hip work daily or every second day','Keep runs shorter than the point where pain starts. Avoid downhills and cambered roads. Raise cadence by 5–10%.'),
('itbs',2,'Hip strength and control','3–4 weeks','Build hip strength in standing and single-leg positions.','Phase 1 exit criteria met.','45 min run including some gentle downhills, pain-free.','3 × per week','Build volume steadily; reintroduce gentle downhills.'),
('itbs',3,'Return to full load','2–4 weeks','Heavier strength and lateral power.','Phase 2 exit criteria met.','Full training including long runs and downhills pain-free.','2 × per week','Back to normal training; add long runs and downhills gradually.'),
('calf',1,'Protect and restore walking','Days 1–7','Walk normally and start gentle loading.','Calf strain; able to walk.','Normal walking pain-free; 15 double-leg calf raises at pain ≤2/10.','Daily','No running. Easy bike if pain-free.'),
('calf',2,'Strength','1–3 weeks','Rebuild calf strength in both straight and bent knee.','Phase 1 exit criteria met.','25 single-leg calf raises each side, within 10% of the other leg; 10 single-leg hops each side pain-free.','Every second day','Start the Standard return-to-run plan once exit criteria are met.'),
('calf',3,'Return to run','2–4 weeks','Rebuild running, then elastic strength.','Phase 2 exit criteria met.','30 min run plus strides pain-free.','Running every second day to start','Follow the Standard return-to-run plan. Strides only after 20 min continuous is comfortable.'),
('calf',4,'Speed, hills and sleds','2–4 weeks','Return to fast running and sled work.','Phase 3 exit criteria met.','Full training including speed, hills and sled push.','Normal training','Add hills, then speed. Reintroduce sled push at light loads first.'),
('pht',1,'Isometrics and offload','1–3 weeks','Reduce pain and load the tendon in positions with little hip bend.','Sit-bone pain.','Sitting 30 min at pain ≤2/10; bridge holds pain-free.','Isometrics daily','Flat, easy running only if pain ≤3/10; no hills or speed.'),
('pht',2,'Strength, increasing hip bend','4–8 weeks','Rebuild hamstring strength and gradually add hip flexion.','Phase 1 exit criteria met.','Single-leg bridge 20 reps each side; RDL 3 × 8 at a moderate load pain-free.','3 × per week','Build easy flat volume. No hills yet: uphill running significantly increases hamstring load.'),
('pht',3,'Speed and power','4–6 weeks','Prepare for fast running and hills.','Phase 2 exit criteria met.','Speed, hills and full training pain-free.','2 × per week','Add flat strides first, then flat speed. Introduce short, gentle hills last and build them gradually.'),
('lbp',1,'Calm and move','1–2 weeks','Keep moving comfortably and restore easy movement.','Back, SIJ or hip pain; able to walk.','Walk 30 min comfortably; daily tasks at pain ≤3/10.','Daily','Walking daily. Easy running only if pain ≤3/10 and not worse afterwards.'),
('lbp',2,'Strength and control','3–6 weeks','Build trunk and hip strength in standing positions.','Phase 1 exit criteria met.','Hip hinge and single-leg work at moderate load pain-free; 30 min run comfortable.','3 × per week','Build back to normal easy volume.'),
('lbp',3,'Return to full load','3–6 weeks','Heavy lifting, carries, rotation and race work.','Phase 2 exit criteria met.','Full training including heavy lifting, sleds and carries pain-free.','2–3 × per week','Normal training.');
