insert into public.return_to_run_plans (id,name,prerequisites,progression_rule) values
('standard','Standard return-to-run plan','30 min brisk walk pain-free; 10 single-leg hops each side at pain ≤2/10.','Run every second day. Do each step twice. Move up when pain stays ≤2/10 during the run and is no worse the next morning. If pain rises, drop back one step. After the final step, build running one variable at a time: add days first, then duration, then intensity (hills, speed). Only progress after a week with no increase in symptoms. Hold if symptoms sit at 2–3/10; drop back if they go higher.'),
('bone','Bone stress return-to-run plan','Medical clearance; 45 min brisk walk pain-free on several days; 10 single-leg hops each side at 0/10; no bone tenderness when pressed.','Only with medical clearance. Run every second day on flat, soft surfaces. Do each step 2–3 times. Move up only with 0/10 bone pain during and for 24 hours after. Any bone pain: stop and drop back one step. No speed or hills until 30 min continuous has been comfortable for 2 weeks. After the final step, build one variable at a time with the treating clinician''s guidance.');
